import{_ as s,o as n,c as p,a0 as e}from"./chunks/framework.Cx-5KwGw.js";const u=JSON.parse('{"title":"Ubuntu22.04下搭建Nginx+PHP+MySql服务","description":"","frontmatter":{"title":"Ubuntu22.04下搭建Nginx+PHP+MySql服务","author":"麻瓜【码瓜】","date":"2024-07-03"},"headers":[],"relativePath":"posts/nginxphpmysql.md","filePath":"posts/nginxphpmysql.md"}'),i={name:"posts/nginxphpmysql.md"};function t(l,a,o,c,d,h){return n(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="ubuntu22-04下搭建nginx-php-mysql服务" tabindex="-1">Ubuntu22.04下搭建Nginx+PHP+MySql服务 <a class="header-anchor" href="#ubuntu22-04下搭建nginx-php-mysql服务" aria-label="Permalink to &quot;Ubuntu22.04下搭建Nginx+PHP+MySql服务&quot;">​</a></h1><h2 id="搭建环境" tabindex="-1">搭建环境 <a class="header-anchor" href="#搭建环境" aria-label="Permalink to &quot;搭建环境&quot;">​</a></h2><p><code>Ubuntu22.04</code></p><h2 id="更新apt" tabindex="-1">更新apt <a class="header-anchor" href="#更新apt" aria-label="Permalink to &quot;更新apt&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt update</span></span></code></pre></div><h2 id="安装相应的服务" tabindex="-1">安装相应的服务 <a class="header-anchor" href="#安装相应的服务" aria-label="Permalink to &quot;安装相应的服务&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apt install nginx mysql-server php-fpm php8.1-xml php-mysql php-gd -y</span></span></code></pre></div><p>注意，确保php8.1-xml要和php需要安装的版本相对应，否则就是要安装php*.*-xml了，<br> 如果不能确定安装的版本，可以先不安装php8.1-xml，等安装完php确定版本后再补安装php-xml。</p><h2 id="检测版本-非必须运行" tabindex="-1">检测版本（非必须运行） <a class="header-anchor" href="#检测版本-非必须运行" aria-label="Permalink to &quot;检测版本（非必须运行）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nginx -v</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>php -v</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql -V</span></span></code></pre></div><h2 id="配置nginx服务" tabindex="-1">配置nginx服务 <a class="header-anchor" href="#配置nginx服务" aria-label="Permalink to &quot;配置nginx服务&quot;">​</a></h2><p>打开nginx默认配置目录</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd /etc/nginx/conf.d</span></span></code></pre></div><p>新建一个.conf配置文件（nginx会遍历该目录下所有配置文件）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim xxxx.conf</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server{</span></span>
<span class="line"><span>        listen 80 ;</span></span>
<span class="line"><span>        root /var/www/wordpress;</span></span>
<span class="line"><span>        index index.php index.html index.htm index.nginx-debian.html;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        server_name domain.com www.domain.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        location / {</span></span>
<span class="line"><span>                try_files $uri $uri/ /index.php?$args;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>        location ~ \\.php$ {</span></span>
<span class="line"><span>                include snippets/fastcgi-php.conf;</span></span>
<span class="line"><span>                fastcgi_pass unix:/run/php/php8.1-fpm.sock;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="配置数据库" tabindex="-1">配置数据库 <a class="header-anchor" href="#配置数据库" aria-label="Permalink to &quot;配置数据库&quot;">​</a></h2><p>进入数据库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql</span></span></code></pre></div><p>进入mysql数据库，该数据库用于存放mysql设置相关的内容</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>USE mysql;</span></span></code></pre></div><p>设置数据库登录密码</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ALTER USER &#39;root&#39;@&#39;localhost&#39; IDENTIFIED WITH mysql_native_password BY &#39;密码&#39;;</span></span></code></pre></div><p>设置数据库访问权限（本地访问/外部访问/限定访问）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>update user set host = &#39;%&#39; where user = &#39;root&#39;;</span></span></code></pre></div><p>设置更新数据库权限</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FLUSH PRIVILEGES;</span></span></code></pre></div><p>退出数据库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>quit;</span></span></code></pre></div><p>下次再进入数据库</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mysql -u root -p</span></span></code></pre></div><p>输入密即可再次进入数据库</p><h2 id="配置php" tabindex="-1">配置php <a class="header-anchor" href="#配置php" aria-label="Permalink to &quot;配置php&quot;">​</a></h2><p>php采用默认配置即可，如果需要自己配置，文件位置：<br><code>/etc/php/8.1/fpm/php.ini</code></p>`,36)])])}const g=s(i,[["render",t]]);export{u as __pageData,g as default};
